import { Router } from "express";
import auth from "./auth.route.js";
import games from "./games.route.js";
import users from "./users.route.js";
import location from "./location.route.js";
import billing from "./billing.route.js";
import puzzles from "./puzzles.route.js";
import tournaments from "./tournaments.route.js";
const router = Router();
router.use("/games", games);
router.use("/auth", auth);
router.use("/users", users);
router.use("/location", location);
router.use("/billing", billing);
router.use("/puzzles", puzzles);
router.use("/tournaments", tournaments);
export default router;
